jQuery(document).ready(function($){
	$('img[usemap]').maphilight({
        fillOpacity   : 1,
        fillColor     : 'e65505',
        stroke        : true,
        strokeColor   : 'FFFFFF',
        strokeWidth   : 3
    });
	$('img[usemap]').rwdImageMaps();
});

jQuery(window).bind('resize', function(e)
{
    window.resizeEvt;
    jQuery(window).resize(function()
    {
        clearTimeout(window.resizeEvt);
        window.resizeEvt = setTimeout(function()
        {
            jQuery('img[usemap]').maphilight({
                fillOpacity   : 1,
                fillColor     : 'e65505',
                stroke        : true,
                strokeColor   : 'FFFFFF',
                strokeWidth   : 3
            });
        }, 250);
    });
});

$(document).ready(function(){

    $(".popup-place").hide();

    $(".responsive-map area").mouseover(function(e) {
        e.preventDefault;

        var id = $(this).data("id");
        var title = $(this).attr( "alt" );
        // console.log("sei su: "+id+" - titolo: "+title);

        // $('#opas-map-highlight .bg-image').css("background-image", mapitaly[id].bg_img);

        // nasconde default tooltip
        $(this).removeAttr('title');

        //pageX/Y gives the coordinates relative to the <html> element in CSS pixels.
        //clientX/Y gives the coordinates relative to the viewport in CSS pixels.
        //screenX/Y gives the coordinates relative to the screen in device pixels.
        //console.log(e.pageX, e.pageY);
        //console.log(e.clientX, e.clientY);
        //console.log(e.screenX, e.screenY);
        var xOffset = Math.max(document.documentElement.scrollLeft,document.body.scrollLeft);
        var yOffset = Math.max(document.documentElement.scrollTop,document.body.scrollTop);
        xOffset -= 50; // flickering
        yOffset += 25; // flickering
        if ($(window).width() <= 768) {
            xOffset += 20; // flickering
            yOffset -= 350; // flickering
        }
        $(".popup-place").css({top: (e.clientY+yOffset) + 'px', left: (e.clientX+xOffset) + 'px', position:'absolute'});
        $(".popup-place").show();
        $(".popup-place h3").text(title);
        $('.popup-place img').attr("src", mapitaly[id].logo);
        // console.log("sei su: "+ mapitaly[id].logo);
        $(".popup-place h6 strong").text(mapitaly[id].status);
        if(mapitaly[id].status == "Operativo"){
            $(".popup-place h6 strong").addClass("text-info");
            $(".popup-place h6 strong").removeClass("text-success");
        }else{
            $(".popup-place h6 strong").removeClass("text-info");
            $(".popup-place h6 strong").addClass("text-success");
        }
        // console.log("sei su: "+ mapitaly[id].status);
    });

    $(".responsive-map area").mouseout(function() {
        $(".popup-place").hide();
    });

});